function M({registerIndicator:k,sourceValues:Y,nulls:w}){k({id:"oa-kurtosis",name:"Kurtosis, tailedness (KURTOSIS)",category:"Statistics",placement:"pane",inputs:[{key:"period",type:"number",label:"Period",default:14,min:4,max:5e3,step:1,tooltip:"At least four samples are needed before a kurtosis can be formed."},{key:"source",type:"source",label:"Source",default:"close"}],plots:[{key:"kurtosis",type:"line",title:"Kurtosis",style:{color:"#ffeb3b",lineWidth:2}}],calc(r,y){const N=Math.max(4,Math.floor(Number(y.period)||14)),x=Y(r,y.source??"close"),a=new Array(r.length).fill(NaN),b=new Array(N).fill(NaN);let c=0,u=0,m=0,f=0,n=0,s=0,d=!1;for(let l=0;l<r.length;l++){const t=d?b[s]:NaN;Number.isFinite(t)&&(c-=t,u-=t*t,m-=t*t*t,f-=t*t*t*t,n-=1);const e=x[l];if(b[s]=e,Number.isFinite(e)&&(c+=e,u+=e*e,m+=e*e*e,f+=e*e*e*e,n+=1),s=(s+1)%N,!d&&s===0&&(d=!0),n<4)continue;const i=n,o=c/i,h=u/i,K=m/i,S=f/i,p=Math.max(h-o*o,0);if(p>1e-10){const A=S-4*o*K+6*o*o*h-3*o*o*o*o;a[l]=A/(p*p)-3}else a[l]=0}return{kurtosis:w(a)}}})}export{M as default};
